## Solução 1: Retornar o valor e usar no final

Se você precisa usar o valor **depois** da chamada, uma abordagem comum é retornar o valor da análise e capturar em outro ponto. Mas como no Flow você geralmente só tem acesso ao contexto via callbacks, o mais prático é **armazenar o valor num global do próprio contexto** ou **usar uma variável persistente do ambiente**.

### Opção A: Guardar no `context` (recomendado para o caso simples)

```javascript
const { Analysis, Device, Utils, Account, Services } = require("@tago-io/sdk");

async function myAnalysis(context, scope) {
    const env_vars = Utils.envToJson(context.environment);
    if (!env_vars.account_token) {
        return context.log("Missing account_token on environment parameters");
    }

    // Guarda a variável no próprio contexto para persistir na execução
    context.accessValue = null;

    const account = new Account({ token: env_vars.account_token });
    const user_id = "66425cdf59aa3c0008518bc3";
    const run = account.run;

    await run.userInfo(user_id).then((result) => {
        result.tags.forEach(tag => {
            if (tag.key === 'access') {
                context.accessValue = tag.value; // guarda no contexto
            }
        });

        console.log("Valor da chave 'access':", context.accessValue);

        if (context.accessValue === 'admin') {
            context.log("O usuário tem acesso de admin.");
        } else {
            context.log("O usuário não tem acesso de admin.");
        }
    }).catch((error) => {
        console.error("Erro ao buscar o usuário:", error);
    });

    // Aqui já conseguimos acessar!
    // Mas atenção: se a análise terminar aqui, o log pode não aparecer.
    // Se precisar usar depois, use o contexto como armazenamento.
}

module.exports = new Analysis(myAnalysis);
